import{_ as r,l as o,o as e,c as d,v as i,p as m,x as n,d as s,i as l,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"汉明距离","description":"","frontmatter":{"title":"汉明距离","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hamming-distance.md","filePath":"cs/hamming-distance.md","lastUpdated":1789023840000}'),_={name:"cs/hamming-distance.md"};function h(E,a,p,A,u,g){const t=o("Mermaid");return e(),d("div",null,[a[1]||(a[1]=i('<h1 id="汉明距离" tabindex="-1">汉明距离 <a class="header-anchor" href="#汉明距离" aria-label="Permalink to &quot;汉明距离&quot;">​</a></h1><div class="epigraph"><p>两个等长串的距离，就是相异位数；码的能耐，首先是最近的两个合法字隔开多远。</p><footer>—— 据 Hamming, Error Detecting and Error Correcting Codes, 1950 整理</footer></div><p>上一课<a href="/cs/error-correcting-intuition">纠错码直觉</a>已经用「相异位数」和 \\(d_{\\min}\\) 说明检、纠半径，并把奇偶、Hamming \\((7,4)\\) 当例子。本课不重讲「为何留空隙」，也不从 Shannon 容量另起。缺口是：距离还只是直觉。后课奇偶与 CRC 要在这把尺子上算，必须把它写成<strong>度量</strong>，并问球能装多满。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记 \\(d(u,v)\\) 为 \\(u,v\\in\\Sigma^n\\) 上取值不同的坐标个数。上一课用它定义 \\(d_{\\min}\\)。缺口因此不是新的熵，而是确认：\\(d\\) 满足正定、对称、三角不等式，从而最近邻译码「球半径 \\(t\\)、要求 \\(2t+1\\le d_{\\min}\\)」有几何意义。重量 \\(w(u)=d(u,0)\\)，线性码里距离由重量决定——线性结构下一课多项式校验才用上，本课先承认这一句。</p><p>Hamming 界：半径 \\(t\\) 的球体积 \\(\\sum_{i=0}^{t}\\binom{n}{i}\\) 乘 \\(|C|\\) 不超过 \\(2^n\\)。本课只钉这个计数上界；\\(\\binom{n}{i}\\) 的系统计数在更后的<a href="/cs/counting-combinatorics">组合计数</a>才展开，这里当球内点数用。</p><h3 id="距离不是熵" tabindex="-1">距离不是熵 <a class="header-anchor" href="#距离不是熵" aria-label="Permalink to &quot;距离不是熵&quot;">​</a></h3><p>上一课<a href="/cs/mutual-information">互信息</a>管平均不确定度。\\(d\\) 不管 \\(p\\)：最坏情况下翻 \\(t\\) 位是否仍落在正确译码球里。把误码率当成 \\(d_{\\min}\\)，会把几何与概率再搅回去。</p><p><span class="marginnote">Hamming 1950 同时给出距离、\\((7,4)\\) 码与奇偶校验思想。三角不等式保证「走两步」不会比直达更近到自相矛盾；译码球因此最多两两不交。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>验证度量公理（三角：翻到中间再翻到终点，翻转次数可加）。码 \\(C\\) 的 \\(d_{\\min}=\\min_{c\\neq c&#39;}d(c,c&#39;)\\)。检 \\(d_{\\min}-1\\) 位错、纠 \\(\\lfloor(d_{\\min}-1)/2\\rfloor\\) 位错。重复码、偶校验（\\(d_{\\min}=2\\)）、Hamming 码（\\(d_{\\min}=3\\)）是同一把尺子上的三个刻度。</p>',11)),(e(),m(c,null,{default:n(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INTU%5B%22%E7%BA%A0%E9%94%99%E7%9B%B4%E8%A7%89%EF%BC%9A%E7%95%99%E7%A9%BA%E9%9A%99%22%5D%20--%3E%20MET%5B%22%E5%BA%A6%E9%87%8F%20d%22%5D%0A%20%20MET%20--%3E%20BALL%5B%22%E8%AF%91%E7%A0%81%E7%90%83%E5%8D%8A%E5%BE%84%20t%22%5D%0A%20%20BALL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%A5%87%E5%81%B6%E4%B8%8E%E5%BE%AA%E7%8E%AF%E6%A0%A1%E9%AA%8C%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>存储 ECC、总线奇偶，硬件上是按位异或累加——实现是后课布尔与门。本课只规定：校验位的作用是把 \\(d_{\\min}\\) 抬上去。最短路、编辑距离是另一类度量，对象不是固定长度比特翻；不要把 Levenshtein 提前塞进 Hamming。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不构造生成矩阵，不证明 Hamming 码完美（球填满空间）。Reed–Solomon 的符号距离不是比特汉明距离，后课存储阵列若用它，须换字母表。主动篡改不是独立翻转，完整性用 MAC，不是 \\(d_{\\min}\\)。</p><p>后课默认：检错纠错先问 \\(d_{\\min}\\)；奇偶是 \\(d=2\\) 的特例，CRC 是同一尺子上的多项式做法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>汉明距离是相异位数，构成度量；\\(d_{\\min}\\) 决定检、纠半径。</li><li>Hamming 界用球体积限制码大小。</li><li>几何与熵分工：本课只管最坏翻转。</li><li>出处：Hamming, <em>Error Detecting and Error Correcting Codes</em>, 1950。</li></ul>',7))])}const B=r(_,[["render",h]]);export{C as __pageData,B as default};
